const { a, b, ...c } = { a: 1, b: 2, x: 3, y: 4 };
console.log(a, b); // 1 2
console.log(c);    // { x: 3, y: 4 } — a new object of the rest

// handy 'omit' pattern:
const user = { id: 1, name: 'Ada', password: 'secret' };
const { password, ...safe } = user;
console.log(safe); // { id: 1, name: 'Ada' }
```

modern-spread-rest-001.example:
```js
// spread: expand into individual values
console.log(Math.max(...[1, 5, 3])); // 5
const merged = [...[1, 2], ...[3, 4]]; // [1, 2, 3, 4]
console.log(merged);

// rest: collect arguments into an array
function sum(...nums) { return nums.reduce((a, b) => a + b, 0); }
console.log(sum(1, 2, 3, 4)); // 10
```

modern-spread-rest-002.example:
```js
// INVALID — SyntaxError: Rest element must be last element
// function foo(...a, b) {}

// VALID — rest is last and collects the remainder
function foo(first, ...rest) { return { first, rest }; }
console.log(foo(1, 2, 3, 4)); // { first: 1, rest: [ 2, 3, 4 ] }
```

modern-esm-001.example:
```js
// A module (e.g. mod.js) can mix ONE default with MANY named exports:
export const foo = 1;                            // named
export function helper() { return 'help'; }      // named
export default function main() { return 'hi'; }  // default

// In another file you'd import them on one line:
//   import main, { foo, helper as h } from './mod.js';
//   - main : default → any name, no braces
//   - foo  : named   → exact name, braces
console.log(foo, helper(), main()); // 1 help hi
```

