array-forEach-002.example:
```js
const wait = (v) => new Promise((r) => setTimeout(() => r(v), 10));

[1, 2].forEach(async (n) => console.log('forEach', await wait(n)));
console.log('runs BEFORE the forEach results — not awaited');

async function correct() {
  for (const n of [1, 2]) console.log('for-of', await wait(n)); // sequential
}
correct();
```

array-forEach-003.example:
```js
[1, 2, 3, 4].forEach((n) => {
  if (n === 3) return; // only skips THIS callback, like continue
  console.log(n);      // 1, 2, 4
});
// to truly short-circuit, use some():
let stoppedAt;
[1, 2, 3, 4].some((n) => (n === 3 ? ((stoppedAt = n), true) : false));
console.log('stopped at', stoppedAt); // 3
```

array-indexOf-002.example:
```js
const a = ['a', 'b', 'a', 'c'];
console.log(a.indexOf('a'));    // 0 — first occurrence
console.log(a.indexOf('a', 1)); // 2 — search starts at index 1
// find all indices of 'a':
const all = [];
for (let i = a.indexOf('a'); i !== -1; i = a.indexOf('a', i + 1)) all.push(i);
console.log(all); // [0, 2]
```

