array-reduce-001.example:
```js
try {
  [].reduce((acc, n) => acc + n); // no initialValue
} catch (e) {
  console.log(e.constructor.name); // TypeError
}
console.log([].reduce((acc, n) => acc + n, 0)); // 0 — safe with initialValue
```

array-reduce-002.example:
```js
let calls = 0;
const r = [10].reduce((acc, n) => { calls++; return acc + n; });
console.log(r, calls); // 10 0 — callback never called, element used as seed

let calls2 = 0;
const r2 = [10].reduce((acc, n) => { calls2++; return acc + n; }, 0);
console.log(r2, calls2); // 10 1 — with initialValue, callback runs once
```

array-reduce-003.example:
```js
const nums = [1, 2, 3];
const withInit = nums.reduce((acc, n, i) => { console.log('i', i); return acc + n; }, 0);
// logs i 0, i 1, i 2  →  withInit = 6
const noInit = nums.reduce((acc, n, i) => { console.log('j', i); return acc + n; });
// logs j 1, j 2       →  noInit = 6 (acc started at nums[0])
console.log(withInit, noInit); // 6 6
```

