array-values-002.example:
```js
const it = ['a', 'b', 'c'].values();
for (const v of it) { /* consume all */ }
for (const v of it) console.log(v); // (nothing) — iterator exhausted

const a = ['a', 'b', 'c'];
for (const v of a) {} // looping the ARRAY makes a fresh iterator each time
for (const v of a) console.log(v); // a | b | c
```

